import 'package:flutter/material.dart'; import 'product_service.dart';
class ProductUploadScreen extends StatefulWidget{const ProductUploadScreen({super.key});@override State<ProductUploadScreen> createState()=>_S();}
class _S extends State<ProductUploadScreen>{final title=TextEditingController(),description=TextEditingController(),price=TextEditingController(),image=TextEditingController();bool loading=false;
Future<void> save()async{setState(()=>loading=true);try{await ProductService().createProduct(title:title.text,description:description.text,price:int.parse(price.text),imageUrl:image.text,latitude:0,longitude:0);if(mounted){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Produk berhasil diunggah. 1 koin digunakan.')));Navigator.pop(context);}}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>loading=false);}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Tambah Produk')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('Tidak ada batas jumlah produk. Setiap upload membutuhkan 1 Koin.'),TextField(controller:title,decoration:const InputDecoration(labelText:'Nama produk')),TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Harga')),TextField(controller:description,maxLines:4,decoration:const InputDecoration(labelText:'Deskripsi manual')),TextField(controller:image,decoration:const InputDecoration(labelText:'URL foto')),const SizedBox(height:20),FilledButton(onPressed:loading?null:save,child:Text(loading?'Mengunggah...':'Upload dengan 1 Koin'))]));}